const raw = $input.first().json;

let data = raw;
if (raw.body !== undefined) {
  let rawBody = raw.body;
  if (typeof rawBody === 'string') {
    rawBody = rawBody.replace(/^=+/, '').trim();
    try { data = JSON.parse(rawBody); } catch(e) { data = raw; }
  } else if (typeof rawBody === 'object') {
    data = rawBody;
  }
}

const task_id     = data.task_id     || raw.task_id     || 'TASK-RUNTIME-' + Date.now();
const environment = data.environment || raw.environment || 'staging';
const incident    = data.incident    || raw.incident    || {
  type: 'none', severity: 'low',
  service_url: 'https://app-' + environment + '.monprojet.com',
  error_message: 'Aucun incident', duration_minutes: 0
};
const monitoring_report = data.monitoring_report || raw.monitoring_report || {
  status: 'HEALTHY', violations: []
};

return [{
  json: {
    task_id:           String(task_id),
    environment:       String(environment),
    incident:          incident,
    monitoring_report: monitoring_report
  }
}];

const input = $input.first().json;

return [{
  json: {
    success: false,
    agent: "Agent Runtime Feedback",
    task_id: "unknown",
    status: "ERROR",
    error_code: input.error_code,
    error_message: input.error_message,
    approved_for_pipeline: false,
    timestamp: input.timestamp
  }
}];

const input = $input.first().json;

const incident_type = input.incident_type || 'unknown';
const severity = input.incident_severity || 'high';
const duration = input.duration_minutes || 0;
const environment = input.environment || 'staging';

const decision_matrix = {
  unavailable: {
    critical: duration > 10 ? 'ROLLBACK' : 'ESCALATE',
    high: 'ESCALATE',
    medium: 'MONITOR'
  },
  crash: { critical: 'ROLLBACK', high: 'ROLLBACK', medium: 'REWORK' },
  timeout: {
    critical: duration > 15 ? 'ROLLBACK' : 'REWORK',
    high: 'REWORK',
    medium: 'MONITOR'
  },
  memory_leak: { critical: 'REWORK', high: 'REWORK', medium: 'MONITOR' },
  error_rate: { critical: 'ROLLBACK', high: 'REWORK', medium: 'MONITOR' },
  unknown: { critical: 'ESCALATE', high: 'ESCALATE', medium: 'MONITOR' }
};

const probable_causes = {
  unavailable: 'Service non démarré ou crash au démarrage',
  crash: 'Exception non gérée ou dépendance manquante',
  timeout: 'Requête DB lente ou ressources insuffisantes',
  memory_leak: 'Objet non libéré ou connexion DB non fermée',
  error_rate: 'Régression dans le dernier déploiement',
  unknown: 'Cause non déterminée — investigation requise'
};

const rework_targets = {
  ROLLBACK: 'Agent DevOps/Deploy',
  REWORK: 'Agent BACKEND',
  ESCALATE: 'Agent Go/No-Go',
  MONITOR: 'Agent Monitoring'
};

const incident_key = decision_matrix[incident_type] ? incident_type : 'unknown';
const severity_key = ['critical','high','medium'].includes(severity) ? severity : 'high';
const action = decision_matrix[incident_key][severity_key];
const cause = probable_causes[incident_key];
const target = rework_targets[action];
const risk_score = severity === 'critical' ? 90 : severity === 'high' ? 65 : 35;

return [{
  json: {
    task_id: input.task_id,
    environment,
    action,
    incident_type,
    severity,
    duration_minutes: duration,
    error_message: input.error_message,
    probable_cause: cause,
    target_agent: target,
    risk_score,
    recommendations: action === 'ROLLBACK'
      ? ['Rollback immédiat vers la version stable', 'Analyser les logs du dernier déploiement']
      : action === 'REWORK'
        ? [`Corriger : ${cause}`, 'Reproduire en environnement de test']
        : action === 'ESCALATE'
          ? ['Escalade vers équipe senior', 'Investigation manuelle requise']
          : ['Continuer la surveillance', 'Vérifier dans 15 minutes']
  }
}];

const input = $input.first().json;

const statusMap = {
  ROLLBACK: 'FAIL',
  REWORK: 'NEEDSIMPROVEMENT',
  ESCALATE: 'FAIL',
  MONITOR: 'PASS'
};

const status = statusMap[input.action] || 'FAIL';
const scoreMap = { PASS: 100, NEEDSIMPROVEMENT: 50, FAIL: 0 };

return [{
  json: {
    agent: "Agent Runtime Feedback",
    task_id: input.task_id,
    status,
    global_score: scoreMap[status],
    approved_for_pipeline: status === 'PASS',
    language: "javascript",
    critical_issues: ['ROLLBACK','ESCALATE'].includes(input.action)
      ? [{ severity: "high", description: `${input.action} requis — ${input.probable_cause}` }]
      : [],
    warnings: input.action === 'REWORK'
      ? [{ severity: "medium", description: input.probable_cause }]
      : [],
    recommendations: input.recommendations || [],
    summary: `Action : ${input.action} — ${input.probable_cause}`,
    dimensions: {
      security: { score: input.risk_score > 70 ? 0 : 100 },
      quality: { score: scoreMap[status] }
    },
    action: input.action,
    target_agent: input.target_agent,
    risk_score: input.risk_score,
    timestamp: new Date().toISOString()
  }
}];

const input = $input.first().json;
return [{
  json: {
    success: false,
    agent: "Agent Runtime Feedback",
    task_id: input.task_id,
    status: "FAIL",
    global_score: 0,
    approved_for_pipeline: false,
    action: input.action,
    target_agent: input.target_agent,
    risk_score: input.risk_score,
    critical_issues: input.critical_issues || [],
    warnings: [],
    recommendations: input.recommendations || [],
    summary: input.summary,
    dimensions: input.dimensions,
    timestamp: input.timestamp
  }
}];

const input = $input.first().json;
return [{
  json: {
    success: null,
    agent: "Agent Runtime Feedback",
    task_id: input.task_id,
    status: "NEEDSIMPROVEMENT",
    global_score: 50,
    approved_for_pipeline: false,
    action: input.action,
    target_agent: input.target_agent,
    risk_score: input.risk_score,
    critical_issues: [],
    warnings: input.warnings || [],
    recommendations: input.recommendations || [],
    summary: input.summary,
    dimensions: input.dimensions,
    timestamp: input.timestamp
  }
}];

const input = $input.first().json;
return [{
  json: {
    success: true,
    agent: "Agent Runtime Feedback",
    task_id: input.task_id,
    status: "PASS",
    global_score: 100,
    approved_for_pipeline: true,
    action: input.action,
    target_agent: input.target_agent,
    risk_score: input.risk_score,
    critical_issues: [],
    warnings: [],
    recommendations: input.recommendations || [],
    summary: input.summary,
    dimensions: input.dimensions,
    timestamp: input.timestamp
  }
}];
